import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
template <typename T>
__global__ void conv3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int D, int H, int Win,
    int OC, int ICg, int K, int stride, int padding, int dilation, int groups,
    int Dout, int Hout, int Wout,
    int nTD, int nTH, int nTW, int IT)
{
  constexpr int Threads    = 256;
  constexpr int PVec       = 2;
  constexpr int OcPerBlock = 16;
  constexpr int TILE       = 8;
  const int tid = threadIdx.x;
  const int n       = blockIdx.z;
  const int OCg = OC / groups;
  const int KVOL = K * K * K;
  // Decode spatial tile from blockIdx.x
  int tile_idx = blockIdx.x;
  int tw_idx = tile_idx % nTW;
  int tmp    = tile_idx / nTW;
  int th_idx = tmp % nTH;
  int td_idx = tmp / nTH;
  const int od_base = td_idx * TILE;
  const int oh_base = th_idx * TILE;
  const int ow_base = tw_idx * TILE;
  const int id_base = od_base * stride - padding;
  const int ih_base = oh_base * stride - padding;
  const int iw_base = ow_base * stride - padding;
  // Strides for X: (N, C, D, H, W) contiguous
  const int64_t sXn = (int64_t)C * D * H * Win;
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  // Strides for Y: (N, OC, Dout, Hout, Wout) contiguous
  const int64_t sYn = (int64_t)OC * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(C, D, H, Win),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(OC, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, ICg, K, K, K),
      make_stride((int64_t)ICg * KVOL, (int64_t)KVOL, (int64_t)(K * K), (int64_t)K, Int<1>{})
  );
  extern __shared__ unsigned char smem_raw[];
  T* smem = reinterpret_cast<T*>(smem_raw);
  const int WChunk = ICg * KVOL; // per output channel weight size
  T* wSmemBase0 = smem;
  T* wSmemBase1 = smem + (size_t)OcPerBlock * (size_t)WChunk;
  T* xSmemBase  = smem + (size_t)2 * (size_t)OcPerBlock * (size_t)WChunk;
  T* wSmemBuf[2] = { wSmemBase0, wSmemBase1 };
  const int IT3 = IT * IT * IT;
  auto sX = make_tensor(
      make_smem_ptr(xSmemBase),
      make_shape(ICg, IT, IT, IT),
      make_stride(IT3, IT * IT, IT, Int<1>{})
  );
  // Precompute the per-thread output-point mapping (reused across all oc tiles).
  int od_arr[PVec], oh_arr[PVec], ow_arr[PVec];
  int ld_arr[PVec], lh_arr[PVec], lw_arr[PVec];
  bool valid_arr[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int lidx = tid + i * Threads;
    int ld  = lidx / (TILE * TILE);
    int rem = lidx % (TILE * TILE);
    int lh  = rem / TILE;
    int lw  = rem % TILE;
    ld_arr[i] = ld; lh_arr[i] = lh; lw_arr[i] = lw;
    int od = od_base + ld;
    int oh = oh_base + lh;
    int ow = ow_base + lw;
    od_arr[i] = od; oh_arr[i] = oh; ow_arr[i] = ow;
    valid_arr[i] = (od < Dout) && (oh < Hout) && (ow < Wout);
  }
  // Loop over all output-channel tiles for this spatial location, reusing the
  // shared-memory input halo tile across every output-channel tile that shares
  // the same group. Weight tiles are staged through a double-buffered pair of
  // shared-memory buffers so that the global-memory load for the NEXT
  // output-channel tile's weights is issued (and can be hidden behind) the
  // arithmetic of the CURRENT tile, instead of a synchronous
  // load-then-sync-then-compute sequence every iteration.
  const int num_oc_tiles = (OC + OcPerBlock - 1) / OcPerBlock;
  int last_ic_base = -1;
  auto load_weight_tile = [&](int tile_idx, T* wbuf) {
    const int base = tile_idx * OcPerBlock;
    const int total_w = OcPerBlock * WChunk;
    const int64_t base_off = (int64_t)base * (int64_t)WChunk;
    const int64_t total_valid = (int64_t)OC * (int64_t)WChunk;
    if ((base_off & 3) == 0) {
      const int total_w4 = total_w / 4;
      for (int idx4 = tid; idx4 < total_w4; idx4 += Threads) {
        int idx = idx4 * 4;
        int64_t gaddr = base_off + idx;
        float4 v;
        if (gaddr + 3 < total_valid) {
          v = *reinterpret_cast<const float4*>(W + gaddr);
        } else {
          float tmp0 = (gaddr + 0 < total_valid) ? (float)W[gaddr + 0] : 0.0f;
          float tmp1 = (gaddr + 1 < total_valid) ? (float)W[gaddr + 1] : 0.0f;
          float tmp2 = (gaddr + 2 < total_valid) ? (float)W[gaddr + 2] : 0.0f;
          float tmp3 = (gaddr + 3 < total_valid) ? (float)W[gaddr + 3] : 0.0f;
          v = make_float4(tmp0, tmp1, tmp2, tmp3);
        }
        *reinterpret_cast<float4*>(wbuf + idx) = v;
      }
      for (int idx = total_w4 * 4 + tid; idx < total_w; idx += Threads) {
        int64_t gaddr = base_off + idx;
        wbuf[idx] = (gaddr < total_valid) ? W[gaddr] : T(0);
      }
    } else {
      for (int idx = tid; idx < total_w; idx += Threads) {
        int64_t gaddr = base_off + idx;
        wbuf[idx] = (gaddr < total_valid) ? W[gaddr] : T(0);
      }
    }
  };
  // Prime the pipeline: load the input halo tile for the first output-channel
  // tile and prefetch its weight tile into buffer 0.
  {
    const int ic_base0 = 0; // oc_base = 0 -> (0/OCg)*ICg = 0
    const int total_x = ICg * IT3;
    for (int idx = tid; idx < total_x; idx += Threads) {
      int ic   = idx / IT3;
      int rem  = idx % IT3;
      int itd  = rem / (IT * IT);
      int rem2 = rem % (IT * IT);
      int ith  = rem2 / IT;
      int itw  = rem2 % IT;
      int id = id_base + itd;
      int ih = ih_base + ith;
      int iw = iw_base + itw;
      T val = T(0);
      if ((unsigned)id < (unsigned)D && (unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
        val = mX(ic_base0 + ic, id, ih, iw);
      }
      sX(ic, itd, ith, itw) = val;
    }
    last_ic_base = ic_base0;
    load_weight_tile(0, wSmemBuf[0]);
    __syncthreads();
  }
  for (int oc_tile = 0; oc_tile < num_oc_tiles; ++oc_tile) {
    const int oc_base = oc_tile * OcPerBlock;
    const int ic_base = (oc_base / OCg) * ICg;
    if (ic_base != last_ic_base) {
      // Group boundary crossed: the resident input halo tile is stale.
      // The previous iteration's ending __syncthreads() already guarantees
      // all reads of sX have completed, so it is safe to overwrite here.
      const int total_x = ICg * IT3;
      for (int idx = tid; idx < total_x; idx += Threads) {
        int ic   = idx / IT3;
        int rem  = idx % IT3;
        int itd  = rem / (IT * IT);
        int rem2 = rem % (IT * IT);
        int ith  = rem2 / IT;
        int itw  = rem2 % IT;
        int id = id_base + itd;
        int ih = ih_base + ith;
        int iw = iw_base + itw;
        T val = T(0);
        if ((unsigned)id < (unsigned)D && (unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
          val = mX(ic_base + ic, id, ih, iw);
        }
        sX(ic, itd, ith, itw) = val;
      }
      __syncthreads();
      last_ic_base = ic_base;
    }
    const int cur_buf = oc_tile & 1;
    auto sW = make_tensor(
        make_smem_ptr(wSmemBuf[cur_buf]),
        make_shape(Int<OcPerBlock>{}, WChunk),
        make_stride(WChunk, Int<1>{})
    );
    const int next_tile = oc_tile + 1;
    if (next_tile < num_oc_tiles) {
      // Issue the loads for the next tile's weights into the other buffer now;
      // these global-memory reads are independent of the compute below and
      // can be hidden behind it (buffer for cur_buf was already validated by
      // the previous iteration's ending __syncthreads()).
      load_weight_tile(next_tile, wSmemBuf[1 - cur_buf]);
    }
    float acc[OcPerBlock][PVec];
    #pragma unroll
    for (int cc = 0; cc < OcPerBlock; ++cc) {
      int oc = oc_base + cc;
      float bval = 0.0f;
      if (B != nullptr && oc < OC) bval = (float)B[oc];
      #pragma unroll
      for (int i = 0; i < PVec; ++i) acc[cc][i] = bval;
    }
    for (int kd = 0; kd < K; ++kd) {
      for (int kh = 0; kh < K; ++kh) {
        for (int kw = 0; kw < K; ++kw) {
          int kk = kd * K * K + kh * K + kw;
          for (int ic = 0; ic < ICg; ++ic) {
            float wreg[OcPerBlock];
            #pragma unroll
            for (int cc = 0; cc < OcPerBlock; ++cc) {
              wreg[cc] = (float) sW(cc, ic * KVOL + kk);
            }
            #pragma unroll
            for (int i = 0; i < PVec; ++i) {
              if (!valid_arr[i]) continue;
              int itd = ld_arr[i] * stride + kd * dilation;
              int ith = lh_arr[i] * stride + kh * dilation;
              int itw = lw_arr[i] * stride + kw * dilation;
              float xval = (float) sX(ic, itd, ith, itw);
              #pragma unroll
              for (int cc = 0; cc < OcPerBlock; ++cc) {
                acc[cc][i] += xval * wreg[cc];
              }
            }
          }
        }
      }
    }
    // Store results
    #pragma unroll
    for (int cc = 0; cc < OcPerBlock; ++cc) {
      int oc = oc_base + cc;
      if (oc >= OC) continue;
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        if (!valid_arr[i]) continue;
        mY(oc, od_arr[i], oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
      }
    }
    __syncthreads(); // ensure this tile's sW reads and the prefetch writes into
                      // the other buffer are complete before they are reused.
  } // end oc_tile loop
}
torch::Tensor conv3d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, C, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [OC, ICg, K, K, K]");
  int64_t N   = x.size(0);
  int64_t C   = x.size(1);
  int64_t D   = x.size(2);
  int64_t H   = x.size(3);
  int64_t Win = x.size(4);
  int64_t OC  = w.size(0);
  int64_t ICg = w.size(1);
  int64_t K   = w.size(2);
  TORCH_CHECK(w.size(3) == K && w.size(4) == K, "kernel must be cubic");
  TORCH_CHECK(C == ICg * groups, "in_channels must equal ICg * groups");
  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Dout = (D + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, OC, Dout, Hout, Wout}, x.options());
  constexpr int Threads    = 256;
  constexpr int OcPerBlock = 16;
  constexpr int TILE       = 8;
  int nTD = (int)((Dout + TILE - 1) / TILE);
  int nTH = (int)((Hout + TILE - 1) / TILE);
  int nTW = (int)((Wout + TILE - 1) / TILE);
  int IT  = (TILE - 1) * stride + (int)(K - 1) * dilation + 1;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)(nTD * nTH * nTW),
      (unsigned)(1),
      (unsigned)N
  );
  size_t smem_bytes = (size_t)2 * (size_t)OcPerBlock * (size_t)ICg * (size_t)(K * K * K) * sizeof(float)
                     + (size_t)ICg * (size_t)IT * (size_t)IT * (size_t)IT * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv3d_kernel<float>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
  }
  conv3d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)D, (int)H, (int)Win,
      (int)OC, (int)ICg, (int)K, stride, padding, dilation, groups,
      (int)Dout, (int)Hout, (int)Wout,
      nTD, nTH, nTW, IT
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 3D convolution with a square kernel, implemented with a single
    custom fused CUDA kernel built on top of CuTe tensors/layouts.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert isinstance(stride, int) and stride >= 1
        assert isinstance(padding, int) and padding >= 0
        assert isinstance(dilation, int) and dilation >= 1
        assert isinstance(groups, int) and groups >= 1
        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        K = self.kernel_size
        ICg = self.in_channels // self.groups
        OC = self.out_channels

        self.weight = nn.Parameter(torch.empty(OC, ICg, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(OC))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

